-- Execute after 01 and 02, against SkillPassport only. Real 1536-dimensional embeddings.
BEGIN;
DO $emb$ DECLARE ids uuid[]; current_profile jsonb; BEGIN
 SELECT array_agg(ctx.id) INTO ids FROM public.role_family_roles ctx
 JOIN public.role ro ON ro.id=ctx.role_id
 JOIN public.role_family_domains fd ON fd.id=ctx.role_family_domain_id
 JOIN public.role_families f ON f.id=fd.role_family_id
 JOIN public.industry_domains ds ON ds.id=fd.industry_domain_id
 JOIN public.domains d ON d.id=ds.domain_id
 JOIN public.industries i ON i.id=ds.industry_id
 WHERE (ro.code='RMR-ROLE-01' OR ro.name='Water Quality Tester') AND (f.code='WAT_RF01' OR f.name='Water Quality Analyst') AND (d.code='WAT_D01' OR d.name='Water Quality & Laboratory Science') AND (i.code='IND_WAT_001' OR i.name='Water & Environmental Services');
 IF cardinality(ids) IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Missing/ambiguous production role context: Water Quality Tester'; END IF;
 SELECT to_jsonb(x) INTO current_profile FROM public.role_family_roles x WHERE id=ids[1];
 IF NOT current_profile @> '{"description": "Tests water samples, accurately records results, checks contradictory readings and identifies further safety tests. Future role: Water Quality Analyst; this school course is career exploration, not a professional qualification.", "observable_behaviours": "Test the Three Coded Liquids: keep cup IDs separate; compare each recorded strip before and after testing; enter the colour observation without assuming the category; Investigate the Cup B Conflict: retain T1 and T2; record a clean-tool fresh-strip T3 separately; compare all three and flag the unexplained T2 conditions; Compare Teacher-Prepared Reference Liquids: match each strip to its own sample, compare observed colours with the correct kit chart and record the classification; Interpret the Fictional R-26 Report: keep pH beside each sample ID; classify A near-neutral, B acidic and C basic; identify untested safety indicators", "role_work_context": "A water-testing laboratory receives labelled samples and must report reliable observations before further safety decisions. Students only investigate prepared school examples.", "typical_work_activities": "Check cup and sample IDs before testing; Observe red and blue litmus before and after contact; Keep Cup B conflicting tests and document a separately controlled retest; Compare reference-liquid results against a kit-specific chart; Interpret reported R-26 pH while noting missing tests", "role_output_evidence": "Coded-liquid indicator observation table; Cup B T1/T2/T3 discrepancy log; Reference-liquid comparison sheet; R-26 reported pH and missing-evidence note; Learning modules: RMR-CAP-L02-M01 - Test the Three Coded Liquids (Core, step 1), RMR-CAP-L02-M02 - Investigate the Cup B Conflict (Important, step 2), RMR-CAP-L05-M01 - Compare Teacher-Prepared Reference Liquids (Important, step 3), RMR-CAP-L05-M04 - Interpret the Fictional R-26 Report (Supporting, step 4)", "primary_riasec": "I", "secondary_riasec": "C", "tertiary_riasec": "R", "riasec_reason": "Investigative work leads because the tester compares evidence and resolves uncertainty; Conventional methods keep sample IDs and readings accurate; Realistic work involves safely handling basic test apparatus.", "degree_gate": "Preferred", "direct_degree_mapping": "B.Sc. Chemistry; B.Sc. Environmental Science; B.Sc. Microbiology; Diploma in Chemical Engineering", "riasec_code_string": "ICR", "aptitude_profile": {"verbal_reasoning": 74, "logical_reasoning": 83, "numerical_reasoning": 75, "data_interpretation": 88, "pattern_recognition": 72, "spatial_reasoning": 52}, "big_five_profile": {"openness": 4, "conscientiousness": 5, "extraversion": 2, "agreeableness": 3, "emotional_stability": 4}, "work_values_profile": {"impact": 5, "status": 3, "autonomy": 3, "security": 4, "financial": 3, "lifestyle": 3, "creativity": 3, "leadership": 2}, "aptitude_assessment": {"areas": ["Data Interpretation", "Logical Reasoning", "Numerical Reasoning"], "rationale": "Water Quality Tester uses data interpretation, logical reasoning, numerical reasoning to check cup and sample ids before testing, observe red and blue litmus before and after contact, and interpret source-based records. These priorities are proposed role demands, not measured learner aptitude."}, "big5_assessment": {"traits": ["Conscientiousness", "Openness", "Emotional Stability"], "rationale": "Water Quality Tester benefits from conscientiousness, openness, emotional stability when performing observe red and blue litmus before and after contact and following through on r-26 reported ph and missing-evidence note. Traits guide supportive coaching, not exclusion."}, "work_values_assessment": {"values": ["Impact", "Security", "Autonomy"], "rationale": "This pathway may reward impact, security, autonomy through the work of check cup and sample ids before testing and producing a clear coded-liquid indicator observation table. These are possible work priorities, not salary or job guarantees."}}'::jsonb THEN RAISE EXCEPTION 'Role profile differs from embedding input: Water Quality Tester'; END IF;
