END $emb$;
DO $emb$ DECLARE ids uuid[]; current_profile jsonb; BEGIN
 SELECT array_agg(ctx.id) INTO ids FROM public.role_family_roles ctx
 JOIN public.role ro ON ro.id=ctx.role_id
 JOIN public.role_family_domains fd ON fd.id=ctx.role_family_domain_id
 JOIN public.role_families f ON f.id=fd.role_family_id
 JOIN public.industry_domains ds ON ds.id=fd.industry_domain_id
 JOIN public.domains d ON d.id=ds.domain_id
 JOIN public.industries i ON i.id=ds.industry_id
 WHERE (ro.code='RMR-ROLE-02' OR ro.name='Water Cleaning Engineer') AND (f.code='WAT_RF02' OR f.name='Water Treatment Engineer') AND (d.code='WAT_D02' OR d.name='Water & Environmental Engineering') AND (i.code='IND_WAT_001' OR i.name='Water & Environmental Services');
 IF cardinality(ids) IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Missing/ambiguous production role context: Water Cleaning Engineer'; END IF;
 SELECT to_jsonb(x) INTO current_profile FROM public.role_family_roles x WHERE id=ids[1];
 IF NOT current_profile @> '{"description": "Designs or improves methods for separating unwanted substances from water and checks whether treatment claims are supported. Future role: Water Treatment Engineer; school activities are introductory demonstrations.", "observable_behaviours": "Transfer and Filter: decant from Jar A into Jar B without disturbing settled soil; pass the liquid through filter paper into Cup C; keep vessel IDs attached to readings; Calculate Salt Solution Concentration: identify mass and volume from the same mixture, apply the taught concentration expression and record the correct units; Inspect What Paper Filtration Retains: distinguish source solutions, observe what the paper retains, and document the filtrate without merging their samples; Evaluate the Filter Advertisement: quote the claim, compare it with supported filtration results, identify missing controls and write a bounded decision", "role_work_context": "A water-treatment engineering team examines how settling, decanting and filters work and whether equipment claims are supported. School experiments are illustrative rather than treatment-plant certification.", "typical_work_activities": "Trace settled soil, decanting and paper-filter operations by vessel ID; Compare suspended soil with dissolved salt; Link mass and volume when describing solution concentration; Examine whether the filter advertisement exceeds the evidence", "role_output_evidence": "Decanting and filtration process record; Salt-solution concentration working; Separate soil and salt filtration log; Filter-claim assessment with evidence limits; Learning modules: RMR-CAP-L01-M02 - Transfer and Filter (Core, step 1), RMR-CAP-L04-M01 - Calculate Salt Solution Concentration (Important, step 2), RMR-CAP-L04-M02 - Inspect What Paper Filtration Retains (Important, step 3), RMR-CAP-L04-M04 - Evaluate the Filter Advertisement (Supporting, step 4)", "primary_riasec": "R", "secondary_riasec": "I", "tertiary_riasec": "C", "riasec_reason": "Realistic work involves physical treatment processes and equipment; Investigative work checks measurements and limitations; Conventional discipline makes calculations and process records traceable.", "degree_gate": "Mandatory", "direct_degree_mapping": "B.Tech. Chemical Engineering; B.Tech. Environmental Engineering; B.Tech. Civil Engineering", "riasec_code_string": "RIC", "aptitude_profile": {"verbal_reasoning": 64, "logical_reasoning": 86, "numerical_reasoning": 88, "data_interpretation": 82, "pattern_recognition": 75, "spatial_reasoning": 85}, "big_five_profile": {"openness": 5, "conscientiousness": 5, "extraversion": 3, "agreeableness": 3, "emotional_stability": 4}, "work_values_profile": {"impact": 5, "status": 4, "autonomy": 4, "security": 4, "financial": 4, "lifestyle": 3, "creativity": 5, "leadership": 4}, "aptitude_assessment": {"areas": ["Numerical Reasoning", "Logical Reasoning", "Spatial Reasoning"], "rationale": "Water Cleaning Engineer uses numerical reasoning, logical reasoning, spatial reasoning to trace settled soil, decanting and paper-filter operations by vessel id, compare suspended soil with dissolved salt, and interpret source-based records. These priorities are proposed role demands, not measured learner aptitude."}, "big5_assessment": {"traits": ["Openness", "Conscientiousness", "Emotional Stability"], "rationale": "Water Cleaning Engineer benefits from openness, conscientiousness, emotional stability when performing compare suspended soil with dissolved salt and following through on filter-claim assessment with evidence limits. Traits guide supportive coaching, not exclusion."}, "work_values_assessment": {"values": ["Impact", "Creativity", "Autonomy"], "rationale": "This pathway may reward impact, creativity, autonomy through the work of trace settled soil, decanting and paper-filter operations by vessel id and producing a clear decanting and filtration process record. These are possible work priorities, not salary or job guarantees."}}'::jsonb THEN RAISE EXCEPTION 'Role profile differs from embedding input: Water Cleaning Engineer'; END IF;
