END $emb$;
DO $emb$ DECLARE ids uuid[]; current_profile jsonb; BEGIN
 SELECT array_agg(ctx.id) INTO ids FROM public.role_family_roles ctx
 JOIN public.role ro ON ro.id=ctx.role_id
 JOIN public.role_family_domains fd ON fd.id=ctx.role_family_domain_id
 JOIN public.role_families f ON f.id=fd.role_family_id
 JOIN public.industry_domains ds ON ds.id=fd.industry_domain_id
 JOIN public.domains d ON d.id=ds.domain_id
 JOIN public.industries i ON i.id=ds.industry_id
 WHERE (ro.code='RMR-ROLE-03' OR ro.name='River Protection Expert') AND (f.code='WAT_RF03' OR f.name='Environmental Scientist') AND (d.code='WAT_D03' OR d.name='Environmental Research & River Protection') AND (i.code='IND_WAT_001' OR i.name='Water & Environmental Services');
 IF cardinality(ids) IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Missing/ambiguous production role context: River Protection Expert'; END IF;
 SELECT to_jsonb(x) INTO current_profile FROM public.role_family_roles x WHERE id=ids[1];
 IF NOT current_profile @> '{"description": "Studies river conditions and helps people understand how environmental changes affect waterways. Future role: Environmental Scientist; the school course supports exploration, not scientific licensure.", "observable_behaviours": "Compare the Two Field Reports: align source ID, conditions, observations and missing fields side by side; identify which differences can be compared fairly; Build a Matched Runoff Comparison: compare the trays, keep the input and slope conditions matched, collect runoff separately and log source-specific readings; Write a Fair Field-Study Proposal: specify the research question, matched variables, measurements and evidence needed; state where conclusions remain limited; Prepare the Water-Authority Handover: summarise verified observations, missing measurements, limits and the responsible next testing or referral action", "role_work_context": "An environmental field team compares conditions near a river and considers land cover, runoff and missing site evidence before recommending further work. Students use model field records.", "typical_work_activities": "Align two field reports by site, conditions and source ID; Compare bare-soil and leaf-covered runoff using matched conditions; Draft a fair field study including the missing slope and rainfall controls; Explain findings and uncertainty in a responsible handover", "role_output_evidence": "Paired field-report comparison; Matched runoff experiment plan; Fair field-study proposal; Water-authority evidence summary; Learning modules: RMR-CAP-L03-M01 - Compare the Two Field Reports (Core, step 1), RMR-CAP-L03-M02 - Build a Matched Runoff Comparison (Important, step 2), RMR-CAP-L03-M04 - Write a Fair Field-Study Proposal (Important, step 3), RMR-CAP-L05-M05 - Prepare the Water-Authority Handover (Supporting, step 4)", "primary_riasec": "I", "secondary_riasec": "S", "tertiary_riasec": "C", "riasec_reason": "Investigative work studies environmental data and source quality; Social interests support community benefit and communication; Conventional methods ensure field evidence can be verified.", "degree_gate": "Preferred", "direct_degree_mapping": "B.Sc. Environmental Science; B.Sc. Geography; B.Sc. Ecology; M.Sc. Environmental Science", "riasec_code_string": "ISC", "aptitude_profile": {"verbal_reasoning": 78, "logical_reasoning": 83, "numerical_reasoning": 70, "data_interpretation": 89, "pattern_recognition": 79, "spatial_reasoning": 70}, "big_five_profile": {"openness": 5, "conscientiousness": 4, "extraversion": 3, "agreeableness": 4, "emotional_stability": 4}, "work_values_profile": {"impact": 5, "status": 3, "autonomy": 4, "security": 3, "financial": 3, "lifestyle": 4, "creativity": 5, "leadership": 3}, "aptitude_assessment": {"areas": ["Data Interpretation", "Logical Reasoning", "Pattern Recognition"], "rationale": "River Protection Expert uses data interpretation, logical reasoning, pattern recognition to align two field reports by site, conditions and source id, compare bare-soil and leaf-covered runoff using matched conditions, and interpret source-based records. These priorities are proposed role demands, not measured learner aptitude."}, "big5_assessment": {"traits": ["Openness", "Conscientiousness", "Agreeableness"], "rationale": "River Protection Expert benefits from openness, conscientiousness, agreeableness when performing compare bare-soil and leaf-covered runoff using matched conditions and following through on water-authority evidence summary. Traits guide supportive coaching, not exclusion."}, "work_values_assessment": {"values": ["Impact", "Creativity", "Autonomy"], "rationale": "This pathway may reward impact, creativity, autonomy through the work of align two field reports by site, conditions and source id and producing a clear paired field-report comparison. These are possible work priorities, not salary or job guarantees."}}'::jsonb THEN RAISE EXCEPTION 'Role profile differs from embedding inpu