END $emb$;
DO $emb$ DECLARE ids uuid[]; current_profile jsonb; BEGIN
 SELECT array_agg(ctx.id) INTO ids FROM public.role_family_roles ctx
 JOIN public.role ro ON ro.id=ctx.role_id
 JOIN public.role_family_domains fd ON fd.id=ctx.role_family_domain_id
 JOIN public.role_families f ON f.id=fd.role_family_id
 JOIN public.industry_domains ds ON ds.id=fd.industry_domain_id
 JOIN public.domains d ON d.id=ds.domain_id
 JOIN public.industries i ON i.id=ds.industry_id
 WHERE (ro.code='RMR-ROLE-04' OR ro.name='Rain & Flood Expert') AND (f.code='WAT_RF04' OR f.name='Hydrologist') AND (d.code='WAT_D04' OR d.name='Hydrology & Watershed Science') AND (i.code='IND_WAT_001' OR i.name='Water & Environmental Services');
 IF cardinality(ids) IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Missing/ambiguous production role context: Rain & Flood Expert'; END IF;
 SELECT to_jsonb(x) INTO current_profile FROM public.role_family_roles x WHERE id=ids[1];
 IF NOT current_profile @> '{"description": "Studies rain, river runoff and land cover to explain water movement and possible flood-related risks. Future role: Hydrologist; these school models do not predict real floods.", "observable_behaviours": "Compare the Two Field Reports: align source ID, conditions, observations and missing fields side by side; identify which differences can be compared fairly; Build a Matched Runoff Comparison: compare the trays, keep the input and slope conditions matched, collect runoff separately and log source-specific readings; Calculate Runoff Across Three Trials: calculate means 160 mL and 100 mL; compute 64% and 40% runoff; report the 24-percentage-point gap", "role_work_context": "A watershed or hydrology team needs fair rainfall-runoff comparisons and repeated data before giving advice about river flow, erosion and possible flood impacts.", "typical_work_activities": "Compare two field reports and identify non-matched conditions; Set up a matched bare-soil versus leaf-cover runoff comparison; Average three model runoff trials for each condition; Compute runoff percentages and state the percentage-point difference without overclaiming soil loss", "role_output_evidence": "Field-report comparison; Matched-tray method and reading log; Three-trial average calculation; Runoff percentage and limitation report; Learning modules: RMR-CAP-L03-M01 - Compare the Two Field Reports (Core, step 1), RMR-CAP-L03-M02 - Build a Matched Runoff Comparison (Important, step 2), RMR-CAP-L03-M03 - Calculate Runoff Across Three Trials (Important, step 3)", "primary_riasec": "I", "secondary_riasec": "R", "tertiary_riasec": "C", "riasec_reason": "Investigative work interprets rainfall and runoff; Realistic work involves physical river and land conditions; Conventional methods require consistent trial records and units.", "degree_gate": "Preferred", "direct_degree_mapping": "B.Tech. Civil Engineering; B.Sc. Geography; B.Sc. Geology; M.Sc. Hydrology", "riasec_code_string": "IRC", "aptitude_profile": {"verbal_reasoning": 67, "logical_reasoning": 86, "numerical_reasoning": 87, "data_interpretation": 91, "pattern_recognition": 80, "spatial_reasoning": 78}, "big_five_profile": {"openness": 5, "conscientiousness": 5, "extraversion": 2, "agreeableness": 3, "emotional_stability": 4}, "work_values_profile": {"impact": 5, "status": 3, "autonomy": 4, "security": 4, "financial": 3, "lifestyle": 4, "creativity": 4, "leadership": 2}, "aptitude_assessment": {"areas": ["Data Interpretation", "Numerical Reasoning", "Logical Reasoning"], "rationale": "Rain & Flood Expert uses data interpretation, numerical reasoning, logical reasoning to compare two field reports and identify non-matched conditions, set up a matched bare-soil versus leaf-cover runoff comparison, and interpret source-based records. These priorities are proposed role demands, not measured learner aptitude."}, "big5_assessment": {"traits": ["Openness", "Conscientiousness", "Emotional Stability"], "rationale": "Rain & Flood Expert benefits from openness, conscientiousness, emotional stability when performing set up a matched bare-soil versus leaf-cover runoff comparison and following through on runoff percentage and limitation report. Traits guide supportive coaching, not exclusion."}, "work_values_assessment": {"values": ["Impact", "Autonomy", "Security"], "rationale": "This pathway may reward impact, autonomy, security through the work of compare two field reports and identify non-matched conditions and producing a clear field-report comparison. These are possible work priorities, not salary or job guarantees."}}'::jsonb THEN RAISE EXCEPTION 'Role profile differs from embedding input: Rain & Flood Expert'; END IF;
