END $emb$;
DO $emb$ DECLARE ids uuid[]; current_profile jsonb; BEGIN
 SELECT array_agg(ctx.id) INTO ids FROM public.role_family_roles ctx
 JOIN public.role ro ON ro.id=ctx.role_id
 JOIN public.role_family_domains fd ON fd.id=ctx.role_family_domain_id
 JOIN public.role_families f ON f.id=fd.role_family_id
 JOIN public.industry_domains ds ON ds.id=fd.industry_domain_id
 JOIN public.domains d ON d.id=ds.domain_id
 JOIN public.industries i ON i.id=ds.industry_id
 WHERE (ro.code='RMR-ROLE-05' OR ro.name='Water Plant Operator') AND (f.code='WAT_RF05' OR f.name='Water Treatment Plant Operator') AND (d.code='WAT_D05' OR d.name='Water Infrastructure Operations') AND (i.code='IND_WAT_001' OR i.name='Water & Environmental Services');
 IF cardinality(ids) IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Missing/ambiguous production role context: Water Plant Operator'; END IF;
 SELECT to_jsonb(x) INTO current_profile FROM public.role_family_roles x WHERE id=ids[1];
 IF NOT current_profile @> '{"description": "Operates and checks water-treatment equipment and records what the process shows. Future role: Water Treatment Plant Operator; professional plant operation needs specific training and supervision.", "observable_behaviours": "Observe the Prepared Water Settle: compare the initial cloudy jar and the settled layers without shaking the jar. Record the liquid and sediment observations at the named times; Transfer and Filter: decant from Jar A into Jar B without disturbing settled soil; pass the liquid through filter paper into Cup C; keep vessel IDs attached to readings; Inspect What Paper Filtration Retains: distinguish source solutions, observe what the paper retains, and document the filtrate without merging their samples", "role_work_context": "A water-treatment facility monitors equipment, keeps operational readings and transfers reliable results for supervisor review. Students examine a simplified classroom separation process, not an operating plant.", "typical_work_activities": "Observe the prepared jar settling without disturbing sediment; Trace Jar A to Jar B to Cup C while recording volume readings; Identify visible material retained on filter paper; Keep equipment observations and exception records for review", "role_output_evidence": "Settling observation sheet; Decanting and filtration transfer log; Filter-paper observation note; Equipment-reading and handover checklist; Learning modules: RMR-CAP-L01-M01 - Observe the Prepared Water Settle (Core, step 1), RMR-CAP-L01-M02 - Transfer and Filter (Important, step 2), RMR-CAP-L04-M02 - Inspect What Paper Filtration Retains (Important, step 3)", "primary_riasec": "R", "secondary_riasec": "C", "tertiary_riasec": "I", "riasec_reason": "Realistic work centres on treatment equipment; Conventional methods protect checklists and readings; Investigative thinking helps spot unexpected changes and refer them for review.", "degree_gate": "Preferred", "direct_degree_mapping": "Diploma in Chemical Engineering; Diploma in Civil Engineering; Diploma in Environmental Engineering; B.Sc. Chemistry", "riasec_code_string": "RCI", "aptitude_profile": {"verbal_reasoning": 58, "logical_reasoning": 78, "numerical_reasoning": 76, "data_interpretation": 77, "pattern_recognition": 76, "spatial_reasoning": 84}, "big_five_profile": {"openness": 3, "conscientiousness": 5, "extraversion": 3, "agreeableness": 4, "emotional_stability": 5}, "work_values_profile": {"impact": 4, "status": 3, "autonomy": 3, "security": 5, "financial": 4, "lifestyle": 3, "creativity": 2, "leadership": 3}, "aptitude_assessment": {"areas": ["Spatial Reasoning", "Logical Reasoning", "Data Interpretation"], "rationale": "Water Plant Operator uses spatial reasoning, logical reasoning, data interpretation to observe the prepared jar settling without disturbing sediment, trace jar a to jar b to cup c while recording volume readings, and interpret source-based records. These priorities are proposed role demands, not measured learner aptitude."}, "big5_assessment": {"traits": ["Conscientiousness", "Emotional Stability", "Agreeableness"], "rationale": "Water Plant Operator benefits from conscientiousness, emotional stability, agreeableness when performing trace jar a to jar b to cup c while recording volume readings and following through on equipment-reading and handover checklist. Traits guide supportive coaching, not exclusion."}, "work_values_assessment": {"values": ["Security", "Impact", "Financial Growth"], "rationale": "This pathway may reward security, impact, financial growth through the work of observe the prepared jar settling without disturbing sediment and producing a clear settling observation sheet. These are possible work priorities, not salary or job guarantees."}}'::jsonb THEN RAISE EXCEPTION 'Role profile differs from embedding input: Water Plant Operator'; END IF;
