END $emb$;
DO $emb$ DECLARE ids uuid[]; current_profile jsonb; BEGIN
 SELECT array_agg(ctx.id) INTO ids FROM public.role_family_roles ctx
 JOIN public.role ro ON ro.id=ctx.role_id
 JOIN public.role_family_domains fd ON fd.id=ctx.role_family_domain_id
 JOIN public.role_families f ON f.id=fd.role_family_id
 JOIN public.industry_domains ds ON ds.id=fd.industry_domain_id
 JOIN public.domains d ON d.id=ds.domain_id
 JOIN public.industries i ON i.id=ds.industry_id
 WHERE (ro.code='RMR-ROLE-06' OR ro.name='Water Safety Officer') AND (f.code='WAT_RF06' OR f.name='Water Quality Compliance Officer') AND (d.code='WAT_D06' OR d.name='Water Quality & Public Safety') AND (i.code='IND_WAT_001' OR i.name='Water & Environmental Services');
 IF cardinality(ids) IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Missing/ambiguous production role context: Water Safety Officer'; END IF;
 SELECT to_jsonb(x) INTO current_profile FROM public.role_family_roles x WHERE id=ids[1];
 IF NOT current_profile @> '{"description": "Reviews test evidence and checks what remains unknown before an authorised water-safety decision. Future role: Water Quality Compliance Officer; students must not approve drinking-water safety.", "observable_behaviours": "Investigate the Cup B Conflict: retain T1 and T2; record a clean-tool fresh-strip T3 separately; compare all three and flag the unexplained T2 conditions; Evaluate the Filter Advertisement: quote the claim, compare it with supported filtration results, identify missing controls and write a bounded decision; Review an Unverified Acid-Base Protocol: list the described steps, identify the missing starting and final evidence and classify the outcome as unverified; Interpret the Fictional R-26 Report: keep pH beside each sample ID; classify A near-neutral, B acidic and C basic; identify untested safety indicators", "role_work_context": "A water-quality assurance team reviews sample evidence, conflicting results and test-method limitations before advising an authorised official. Approval is outside the student role.", "typical_work_activities": "Keep both Cup B observations and identify why a controlled retest is needed; Check whether a filter advertisement is supported by the tests; Mark the acid-base procedure as unverified when before/after evidence is absent; Review R-26 pH reports and missing microbial and chemical tests", "role_output_evidence": "Retest and discrepancy register; Claim-validation decision note; Unverified-protocol findings list; R-26 safety-evidence gap report; Learning modules: RMR-CAP-L02-M02 - Investigate the Cup B Conflict (Core, step 1), RMR-CAP-L04-M04 - Evaluate the Filter Advertisement (Important, step 2), RMR-CAP-L05-M03 - Review an Unverified Acid-Base Protocol (Important, step 3), RMR-CAP-L05-M04 - Interpret the Fictional R-26 Report (Supporting, step 4)", "primary_riasec": "C", "secondary_riasec": "I", "tertiary_riasec": "S", "riasec_reason": "Conventional work ensures records and methods meet review rules; Investigative work identifies unsupported claims; Social responsibility keeps public-facing recommendations careful.", "degree_gate": "Preferred", "direct_degree_mapping": "B.Sc. Chemistry; B.Sc. Environmental Science; B.Tech. Environmental Engineering; M.Sc. Environmental Science", "riasec_code_string": "CIS", "aptitude_profile": {"verbal_reasoning": 85, "logical_reasoning": 89, "numerical_reasoning": 79, "data_interpretation": 92, "pattern_recognition": 76, "spatial_reasoning": 61}, "big_five_profile": {"openness": 4, "conscientiousness": 5, "extraversion": 3, "agreeableness": 4, "emotional_stability": 5}, "work_values_profile": {"impact": 5, "status": 3, "autonomy": 3, "security": 5, "financial": 3, "lifestyle": 3, "creativity": 2, "leadership": 4}, "aptitude_assessment": {"areas": ["Data Interpretation", "Logical Reasoning", "Verbal Reasoning"], "rationale": "Water Safety Officer uses data interpretation, logical reasoning, verbal reasoning to keep both cup b observations and identify why a controlled retest is needed, check whether a filter advertisement is supported by the tests, and interpret source-based records. These priorities are proposed role demands, not measured learner aptitude."}, "big5_assessment": {"traits": ["Conscientiousness", "Emotional Stability", "Agreeableness"], "rationale": "Water Safety Officer benefits from conscientiousness, emotional stability, agreeableness when performing check whether a filter advertisement is supported by the tests and following through on r-26 safety-evidence gap report. Traits guide supportive coaching, not exclusion."}, "work_values_assessment": {"values": ["Impact", "Security", "Leadership"], "rationale": "This pathway may reward impact, security, leadership through the work of keep both cup b observations and identify why a controlled retest is needed and producing a clear retest and discrepancy register. These are possible work priorities, not salary or job guarantees."}}'::js