END $emb$;
DO $emb$ DECLARE ids uuid[]; current_profile jsonb; BEGIN
 SELECT array_agg(ctx.id) INTO ids FROM public.role_family_roles ctx
 JOIN public.role ro ON ro.id=ctx.role_id
 JOIN public.role_family_domains fd ON fd.id=ctx.role_family_domain_id
 JOIN public.role_families f ON f.id=fd.role_family_id
 JOIN public.industry_domains ds ON ds.id=fd.industry_domain_id
 JOIN public.domains d ON d.id=ds.domain_id
 JOIN public.industries i ON i.id=ds.industry_id
 WHERE (ro.code='RMR-ROLE-07' OR ro.name='Water Project Manager') AND (f.code='WAT_RF07' OR f.name='Water Infrastructure Project Manager') AND (d.code='WAT_D07' OR d.name='Water Operations & Planning') AND (i.code='IND_WAT_001' OR i.name='Water & Environmental Services');
 IF cardinality(ids) IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Missing/ambiguous production role context: Water Project Manager'; END IF;
 SELECT to_jsonb(x) INTO current_profile FROM public.role_family_roles x WHERE id=ids[1];
 IF NOT current_profile @> '{"description": "Plans water-related work, organises budgets and prepares clear evidence-based handovers. Future role: Water Infrastructure Project Manager; the school exercises introduce planning only.", "observable_behaviours": "Prepare the School-Tank Evidence Note: use the supported volume and observation records; distinguish what separation shows from what drinking-water safety would require; prepare a short note; Finish the Cost and Finding Log: multiply number of strips by unit cost, subtract expenditure from the budget, and write what the test evidence supports; Write a Fair Field-Study Proposal: specify the research question, matched variables, measurements and evidence needed; state where conclusions remain limited; Prepare the Water-Authority Handover: summarise verified observations, missing measurements, limits and the responsible next testing or referral action", "role_work_context": "A local water-project team must plan evidence collection, track small budgets and prepare decisions for responsible managers or authorities.", "typical_work_activities": "Prepare a school-tank evidence note distinguishing treatment appearance from safety; Calculate indicator-strip spending and available balance; Specify a fair field-study plan with clear controls; Write a water-authority handover with next action and owner", "role_output_evidence": "School-tank evidence note; Strip-cost and balance log; Field-study proposal; Water-authority handover and responsibility record; Learning modules: RMR-CAP-L01-M04 - Prepare the School-Tank Evidence Note (Core, step 1), RMR-CAP-L02-M04 - Finish the Cost and Finding Log (Important, step 2), RMR-CAP-L03-M04 - Write a Fair Field-Study Proposal (Important, step 3), RMR-CAP-L05-M05 - Prepare the Water-Authority Handover (Supporting, step 4)", "primary_riasec": "E", "secondary_riasec": "C", "tertiary_riasec": "S", "riasec_reason": "Enterprising work coordinates tasks and decisions; Conventional practice tracks costs and deliverables; Social work communicates responsibilities across people and authorities.", "degree_gate": "Preferred", "direct_degree_mapping": "B.Tech. Civil Engineering; B.Tech. Environmental Engineering; Bachelor of Business Administration (BBA); Master of Business Administration (MBA)", "riasec_code_string": "ECS", "aptitude_profile": {"verbal_reasoning": 91, "logical_reasoning": 82, "numerical_reasoning": 84, "data_interpretation": 88, "pattern_recognition": 70, "spatial_reasoning": 63}, "big_five_profile": {"openness": 4, "conscientiousness": 5, "extraversion": 5, "agreeableness": 4, "emotional_stability": 4}, "work_values_profile": {"impact": 5, "status": 4, "autonomy": 4, "security": 4, "financial": 4, "lifestyle": 3, "creativity": 4, "leadership": 5}, "aptitude_assessment": {"areas": ["Verbal Reasoning", "Data Interpretation", "Numerical Reasoning"], "rationale": "Water Project Manager uses verbal reasoning, data interpretation, numerical reasoning to prepare a school-tank evidence note distinguishing treatment appearance from safety, calculate indicator-strip spending and available balance, and interpret source-based records. These priorities are proposed role demands, not measured learner aptitude."}, "big5_assessment": {"traits": ["Conscientiousness", "Extraversion", "Agreeableness"], "rationale": "Water Project Manager benefits from conscientiousness, extraversion, agreeableness when performing calculate indicator-strip spending and available balance and following through on water-authority handover and responsibility record. Traits guide supportive coaching, not exclusion."}, "work_values_assessment": {"values": ["Impact", "Leadership", "Autonomy"], "rationale": "This pathway may reward impact, leadership, autonomy through the work of prepare a school-tank evidence note distinguishing treatment appearance from safety and producing a clear school-tank evidence note. These are possible work priorities, not salary or job guarantees."}}'::json