END $emb$;
DO $emb$ DECLARE ids uuid[]; current_profile jsonb; BEGIN
 SELECT array_agg(ctx.id) INTO ids FROM public.role_family_roles ctx
 JOIN public.role ro ON ro.id=ctx.role_id
 JOIN public.role_family_domains fd ON fd.id=ctx.role_family_domain_id
 JOIN public.role_families f ON f.id=fd.role_family_id
 JOIN public.industry_domains ds ON ds.id=fd.industry_domain_id
 JOIN public.domains d ON d.id=ds.domain_id
 JOIN public.industries i ON i.id=ds.industry_id
 WHERE (ro.code='RMR-ROLE-08' OR ro.name='Community Water Helper') AND (f.code='WAT_RF08' OR f.name='Community Water Programme Coordinator') AND (d.code='WAT_D08' OR d.name='Community Water & Environmental Programmes') AND (i.code='IND_WAT_001' OR i.name='Water & Environmental Services');
 IF cardinality(ids) IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Missing/ambiguous production role context: Community Water Helper'; END IF;
 SELECT to_jsonb(x) INTO current_profile FROM public.role_family_roles x WHERE id=ids[1];
 IF NOT current_profile @> '{"description": "Helps communities understand water observations, plan informed action and communicate uncertainty clearly. Future role: Community Water Programme Coordinator; this is school-level career exploration.", "observable_behaviours": "Prepare the School-Tank Evidence Note: use the supported volume and observation records; distinguish what separation shows from what drinking-water safety would require; prepare a short note; Finish the Cost and Finding Log: multiply number of strips by unit cost, subtract expenditure from the budget, and write what the test evidence supports; Write a Fair Field-Study Proposal: specify the research question, matched variables, measurements and evidence needed; state where conclusions remain limited; Prepare the Water-Authority Handover: summarise verified observations, missing measurements, limits and the responsible next testing or referral action", "role_work_context": "A community water programme explains environmental observations and helps residents understand what evidence is reliable and when specialised testing is needed.", "typical_work_activities": "Explain what a school tank or separation demonstration proves and does not prove; Summarise test costs and observations in understandable language; Communicate proposed field-study steps and missing evidence; Prepare a responsible handover without declaring unsafe samples safe", "role_output_evidence": "Plain-language school-water evidence note; Community testing-cost summary; Field-study explanation; Water-authority referral and communication note; Learning modules: RMR-CAP-L01-M04 - Prepare the School-Tank Evidence Note (Core, step 1), RMR-CAP-L02-M04 - Finish the Cost and Finding Log (Important, step 2), RMR-CAP-L03-M04 - Write a Fair Field-Study Proposal (Important, step 3), RMR-CAP-L05-M05 - Prepare the Water-Authority Handover (Supporting, step 4)", "primary_riasec": "S", "secondary_riasec": "E", "tertiary_riasec": "C", "riasec_reason": "Social work involves helping and explaining; Enterprising work coordinates local action; Conventional discipline ensures community messages accurately reflect the evidence.", "degree_gate": "Preferred", "direct_degree_mapping": "Bachelor of Social Work (BSW); B.A. Sociology; B.A. Geography; B.A. Environmental Studies", "riasec_code_string": "SEC", "aptitude_profile": {"verbal_reasoning": 92, "logical_reasoning": 78, "numerical_reasoning": 61, "data_interpretation": 80, "pattern_recognition": 68, "spatial_reasoning": 45}, "big_five_profile": {"openness": 4, "conscientiousness": 4, "extraversion": 5, "agreeableness": 5, "emotional_stability": 4}, "work_values_profile": {"impact": 5, "status": 2, "autonomy": 3, "security": 4, "financial": 3, "lifestyle": 4, "creativity": 4, "leadership": 5}, "aptitude_assessment": {"areas": ["Verbal Reasoning", "Data Interpretation", "Logical Reasoning"], "rationale": "Community Water Helper uses verbal reasoning, data interpretation, logical reasoning to explain what a school tank or separation demonstration proves and does not prove, summarise test costs and observations in understandable language, and interpret source-based records. These priorities are proposed role demands, not measured learner aptitude."}, "big5_assessment": {"traits": ["Agreeableness", "Extraversion", "Openness"], "rationale": "Community Water Helper benefits from agreeableness, extraversion, openness when performing summarise test costs and observations in understandable language and following through on water-authority referral and communication note. Traits guide supportive coaching, not exclusion."}, "work_values_assessment": {"values": ["Impact", "Leadership", "Lifestyle"], "rationale": "This pathway may reward impact, leadership, lifestyle through the work of explain what a school tank or separation demonstration proves and does not prove and producing a clear plain-language school-water evidence note. These are possible work priorities, not salary or job