END $emb$;
DO $emb$ DECLARE ids uuid[]; current_profile jsonb; BEGIN
 SELECT array_agg(ctx.id) INTO ids FROM public.role_family_roles ctx
 JOIN public.role ro ON ro.id=ctx.role_id
 JOIN public.role_family_domains fd ON fd.id=ctx.role_family_domain_id
 JOIN public.role_families f ON f.id=fd.role_family_id
 JOIN public.industry_domains ds ON ds.id=fd.industry_domain_id
 JOIN public.domains d ON d.id=ds.domain_id
 JOIN public.industries i ON i.id=ds.industry_id
 WHERE (ro.code='WAT_RF01_DR01' OR ro.name='Water Quality Field Assistant') AND (f.code='WAT_RF01' OR f.name='Field Sampling and Site Monitoring') AND (d.code='IND_WAT_D01' OR d.name='Water Quality Field and Laboratory Evidence') AND (i.code='IND_WAT_001' OR i.name='Water Resources, Environment and Public Utilities');
 IF cardinality(ids) IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Missing/ambiguous production role context: Water Quality Field Assistant'; END IF;
 SELECT to_jsonb(x) INTO current_profile FROM public.role_family_roles x WHERE id=ids[1];
 IF NOT current_profile @> '{"description": "Water Quality Field Assistant supports obtain reliable field evidence in the RAREMINDS River Mission workplace case. May document and support supervised field work; cannot approve sampling, certify readings, release restricted sites, or declare water safe.", "observable_behaviours": "Map sampling stations from recorded chainage and site evidence; Check site access and monitoring parameters against the approved plan; Support supervised collection; record sample ID, station, collector, time and seal; Link chain-of-custody forms and flag missing calibration or release evidence; Check each saved record against source ID, units, errors and role authority.", "role_work_context": "L1 case and site review \u2192 L2 field and custody evidence \u2192 L5 field-route portfolio. Inputs: S01\u2013S03 site evidence, chainage map, MON-01 stations, sample labels, seal and custody references. Course-wide foundations: CAP01, CAP02, CAP06, CAP07, CAP08, CAP11. Role focus: CAP03, CAP04. May document and support supervised field work; cannot approve sampling, certify readings, release restricted sites, or declare water safe.", "typical_work_activities": "Water Quality Field Assistant: Map sampling stations from recorded chainage and site evidence; Check site access and monitoring parameters against the approved plan; Support supervised collection; record sample ID, station, collector, time and seal; Link chain-of-custody forms and flag missing calibration or release evidence. When source evidence is missing, record a HOLD/exception and identify the reviewing owner.", "role_output_evidence": "Source-backed outputs: Site and station map with source labels; Monitoring route and field-readiness log; Dated sample register and chain-of-custody handover; Readiness exception note for supervisor. Associated capability evidence: CAP01 Investigation brief; CAP02 Stakeholder and site register; CAP03 Monitoring plan; CAP04 Sampling and test record; CAP06 Validated analytical workbook; CAP07 Evidence and hypothesis matrix; CAP08 Criteria comparison and gap report; CAP11 Final professional investigation portfolio.", "primary_riasec": "R", "secondary_riasec": "I", "tertiary_riasec": "C", "riasec_reason": "RIC (Realistic/Investigative/Conventional): R supports field instruments, site observations and physical sampling logistics; I supports checking whether evidence is reliable; C supports accurate labels, logs and custody. Proposed role-environment orientation, not an individual assessment.", "degree_gate": "Preferred", "direct_degree_mapping": "B.Sc. Chemistry; B.Sc. Environmental Science; B.Sc. Zoology; B.Sc. Botany; B.Sc. Geography; B.Sc. Geology; B.Sc. Agriculture; B.F.Sc. Fisheries Science; B.Tech Civil Engineering", "riasec_code_string": "RIC", "aptitude_profile": {"verbal_reasoning": 62, "logical_reasoning": 77, "numerical_reasoning": 75, "data_interpretation": 83, "pattern_recognition": 68, "spatial_reasoning": 88}, "big_five_profile": {"openness": 3, "conscientiousness": 5, "extraversion": 3, "agreeableness": 4, "emotional_stability": 4}, "work_values_profile": {"impact": 5, "status": 2, "autonomy": 3, "security": 4, "financial": 3, "lifestyle": 2, "creativity": 3, "leadership": 2}, "aptitude_assessment": {"areas": ["Spatial Reasoning", "Data Interpretation", "Logical Reasoning"], "rationale": "Locate stations accurately, interpret field readings and identify sample/custody mismatches before handover. These are draft importance estimates for role requirements, not learner aptitude scores; SME review required."}, "big5_assessment": {"traits": ["Conscientiousness", "Emotional Stability", "Agreeableness"], "rationale": "Careful records and calm handling of field exceptions are important when sampling is supervised. Trait-demand ratings are provisional role descriptors, not personality diagnosis or exclusion criteria."}, "work_values_assessment": {"values": ["Impact", "Security", "Autonomy"], "rationale": "Environmental impact, safe procedures and bounded field autonomy are relevant; field visits can vary by site and weather. Work-value ratings are provisional career-exploration descriptors, not employment or pay guarantees."}}'::jsonb THEN RAISE EXCEPTION 'Role profile differs from embedding input: Water Quality Field Assistant'; END IF;
