END $emb$;
DO $emb$ DECLARE ids uuid[]; current_profile jsonb; BEGIN
 SELECT array_agg(ctx.id) INTO ids FROM public.role_family_roles ctx
 JOIN public.role ro ON ro.id=ctx.role_id
 JOIN public.role_family_domains fd ON fd.id=ctx.role_family_domain_id
 JOIN public.role_families f ON f.id=fd.role_family_id
 JOIN public.industry_domains ds ON ds.id=fd.industry_domain_id
 JOIN public.domains d ON d.id=ds.domain_id
 JOIN public.industries i ON i.id=ds.industry_id
 WHERE (ro.code='WAT_RF02_DR01' OR ro.name='Water Quality Laboratory Assistant') AND (f.code='WAT_RF02' OR f.name='Laboratory Sampling and Quality Control') AND (d.code='IND_WAT_D01' OR d.name='Water Quality Field and Laboratory Evidence') AND (i.code='IND_WAT_001' OR i.name='Water Resources, Environment and Public Utilities');
 IF cardinality(ids) IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Missing/ambiguous production role context: Water Quality Laboratory Assistant'; END IF;
 SELECT to_jsonb(x) INTO current_profile FROM public.role_family_roles x WHERE id=ids[1];
 IF NOT current_profile @> '{"description": "Water Quality Laboratory Assistant supports produce and verify analytical evidence in the RAREMINDS River Mission workplace case. Can prepare and review evidence under laboratory supervision; cannot sign accredited reports or certify unverified tests.", "observable_behaviours": "Check sample ID, seal, receipt and laboratory accession link; Prepare samples and follow approved test procedures under supervision; Record readings with parameter, unit, method and source ID; Compare raw and reviewed values; record QC discrepancies without overwriting raw evidence; Check each saved record against source ID, units, errors and role authority.", "role_work_context": "L2 laboratory accession, reading and QC \u2192 L3 analysis review \u2192 L5 laboratory-route portfolio. Inputs: sample accession, LAB_RAW and LAB_QC entries, pH/DO/BOD and microbial results, method and certificate references. Course-wide foundations: CAP01, CAP02, CAP06, CAP07, CAP08, CAP11. Role focus: CAP04, CAP05. Can prepare and review evidence under laboratory supervision; cannot sign accredited reports or certify unverified tests.", "typical_work_activities": "Water Quality Laboratory Assistant: Check sample ID, seal, receipt and laboratory accession link; Prepare samples and follow approved test procedures under supervision; Record readings with parameter, unit, method and source ID; Compare raw and reviewed values; record QC discrepancies without overwriting raw evidence. When source evidence is missing, record a HOLD/exception and identify the reviewing owner.", "role_output_evidence": "Source-backed outputs: Sample accession and method checklist; Laboratory results and comparison sheet; QC exception and corrected-value audit; Provisional evidence handover for qualified laboratory reviewer. Associated capability evidence: CAP01 Investigation brief; CAP02 Stakeholder and site register; CAP04 Sampling and test record; CAP05 Laboratory comparison sheet; CAP06 Validated analytical workbook; CAP07 Evidence and hypothesis matrix; CAP08 Criteria comparison and gap report; CAP11 Final professional investigation portfolio.", "primary_riasec": "I", "secondary_riasec": "R", "tertiary_riasec": "C", "riasec_reason": "IRC (Investigative/Realistic/Conventional): I supports analytical questions and method validation; R supports instruments and laboratory procedure; C supports traceable sample records. Proposed role-environment orientation, not an individual assessment.", "degree_gate": "Preferred", "direct_degree_mapping": "B.Sc. Chemistry; B.Sc. Environmental Science; B.Sc. Microbiology; B.Sc. Biotechnology; B.Tech Environmental Engineering; B.Tech Chemical Engineering", "riasec_code_string": "IRC", "aptitude_profile": {"verbal_reasoning": 61, "logical_reasoning": 86, "numerical_reasoning": 89, "data_interpretation": 91, "pattern_recognition": 82, "spatial_reasoning": 58}, "big_five_profile": {"openness": 3, "conscientiousness": 5, "extraversion": 2, "agreeableness": 3, "emotional_stability": 4}, "work_values_profile": {"impact": 5, "status": 2, "autonomy": 3, "security": 5, "financial": 3, "lifestyle": 3, "creativity": 3, "leadership": 2}, "aptitude_assessment": {"areas": ["Data Interpretation", "Numerical Reasoning", "Logical Reasoning"], "rationale": "Read laboratory measurements, use the correct units and methods, and notice incompatible or anomalous results. These are draft importance estimates for role requirements, not learner aptitude scores; SME review required."}, "big5_assessment": {"traits": ["Conscientiousness", "Emotional Stability", "Openness"], "rationale": "Method discipline and sustained attention help prevent sample and data-release errors. Trait-demand ratings are provisional role descriptors, not personality diagnosis or exclusion criteria."}, "work_values_assessment": {"values": ["Impact", "Security", "Autonomy"], "rationale": "Reliable analytical evidence and safe, repeatable procedures are important; formal sign-