END $emb$;
DO $emb$ DECLARE ids uuid[]; current_profile jsonb; BEGIN
 SELECT array_agg(ctx.id) INTO ids FROM public.role_family_roles ctx
 JOIN public.role ro ON ro.id=ctx.role_id
 JOIN public.role_family_domains fd ON fd.id=ctx.role_family_domain_id
 JOIN public.role_families f ON f.id=fd.role_family_id
 JOIN public.industry_domains ds ON ds.id=fd.industry_domain_id
 JOIN public.domains d ON d.id=ds.domain_id
 JOIN public.industries i ON i.id=ds.industry_id
 WHERE (ro.code='WAT_RF03_DR01' OR ro.name='Environmental Data Analyst') AND (f.code='WAT_RF03' OR f.name='Environmental Data Analytics') AND (d.code='IND_WAT_D02' OR d.name='Environmental Data and Analysis') AND (i.code='IND_WAT_001' OR i.name='Water Resources, Environment and Public Utilities');
 IF cardinality(ids) IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Missing/ambiguous production role context: Environmental Data Analyst'; END IF;
 SELECT to_jsonb(x) INTO current_profile FROM public.role_family_roles x WHERE id=ids[1];
 IF NOT current_profile @> '{"description": "Environmental Data Analyst supports convert measurements into findings in the RAREMINDS River Mission workplace case. May analyse and report source-backed patterns; cannot certify laboratory methods, infer a proven source without evidence or authorise corrective actions.", "observable_behaviours": "Import records and verify data types, keys and source IDs; Join laboratory and field evidence on exact sample ID; Clean data, calculate station and campaign differences and flag anomalies; Build chart/filter views and record interpretation limits; Check each saved record against source ID, units, errors and role authority.", "role_work_context": "L3 source import, join, comparison, dashboard and findings \u2192 L5 analyst-route portfolio. Inputs: six accepted sample IDs, field and laboratory source tables, campaign dates, DO/BOD comparisons and missing-key exceptions. Course-wide foundations: CAP01, CAP02, CAP06, CAP07, CAP08, CAP11. Role focus: CAP05, CAP06. May analyse and report source-backed patterns; cannot certify laboratory methods, infer a proven source without evidence or authorise corrective actions.", "typical_work_activities": "Environmental Data Analyst: Import records and verify data types, keys and source IDs; Join laboratory and field evidence on exact sample ID; Clean data, calculate station and campaign differences and flag anomalies; Build chart/filter views and record interpretation limits. When source evidence is missing, record a HOLD/exception and identify the reviewing owner.", "role_output_evidence": "Source-backed outputs: Clean, joined and traceable analysis table; Data exception and reconciliation log; Comparative Excel dashboard with filters; Qualified analytical findings and source-backed handover. Associated capability evidence: CAP01 Investigation brief; CAP02 Stakeholder and site register; CAP05 Laboratory comparison sheet; CAP06 Validated analytical workbook; CAP07 Evidence and hypothesis matrix; CAP08 Criteria comparison and gap report; CAP11 Final professional investigation portfolio.", "primary_riasec": "I", "secondary_riasec": "C", "tertiary_riasec": "R", "riasec_reason": "ICR (Investigative/Conventional/Realistic): I supports investigating anomalies; C supports accurate datasets and repeatable formulas; R reflects the use of quantitative monitoring instruments and evidence. Proposed role-environment orientation, not an individual assessment.", "degree_gate": "Preferred", "direct_degree_mapping": "B.Sc. Environmental Science; B.Sc. Biotechnology; B.Sc. Geography; B.Sc. Geology; B.Tech Computer Science Engineering; B.Tech Information Technology; BCA; MCA; B.Sc. Statistics; B.Sc. Mathematics; B.Sc. Data Science; B.Sc. Artificial Intelligence; Geoinformatics / Remote Sensing; Public Health programmes", "riasec_code_string": "ICR", "aptitude_profile": {"verbal_reasoning": 70, "logical_reasoning": 92, "numerical_reasoning": 94, "data_interpretation": 96, "pattern_recognition": 90, "spatial_reasoning": 65}, "big_five_profile": {"openness": 5, "conscientiousness": 5, "extraversion": 2, "agreeableness": 3, "emotional_stability": 4}, "work_values_profile": {"impact": 5, "status": 3, "autonomy": 4, "security": 4, "financial": 4, "lifestyle": 4, "creativity": 5, "leadership": 3}, "aptitude_assessment": {"areas": ["Data Interpretation", "Logical Reasoning", "Numerical Reasoning"], "rationale": "Exact-key joins, calculations, charts and QA checks require strong numeric and data reasoning. These are draft importance estimates for role requirements, not learner aptitude scores; SME review required."}, "big5_assessment": {"traits": ["Conscientiousness", "Openness", "Emotional Stability"], "rationale": "Curiosity finds anomalies while systematic checking keeps analytical conclusions traceable. Trait-demand ratings are provisional role descriptors, not personality diagnosis or exclusion criteria."}, "work_values_assessment": {"values": ["Impact", "Autonomy", "Creativity"], "rationale": "The role offers analytical problem solving and evidence-based environmental impact, not regulatory authority. Work-value ratings are provisional career-exploration descriptors, not employment or pay guarantees."}}'::jsonb THEN RAISE EXCEPTION 'Role profile differs from embedding input: Environmental Data Analyst'; END IF;
