END $emb$;
DO $emb$ DECLARE ids uuid[]; current_profile jsonb; BEGIN
 SELECT array_agg(ctx.id) INTO ids FROM public.role_family_roles ctx
 JOIN public.role ro ON ro.id=ctx.role_id
 JOIN public.role_family_domains fd ON fd.id=ctx.role_family_domain_id
 JOIN public.role_families f ON f.id=fd.role_family_id
 JOIN public.industry_domains ds ON ds.id=fd.industry_domain_id
 JOIN public.domains d ON d.id=ds.domain_id
 JOIN public.industries i ON i.id=ds.industry_id
 WHERE (ro.code='WAT_RF04_DR01' OR ro.name='Water Treatment Operations Assistant') AND (f.code='WAT_RF04' OR f.name='Treatment Process Operations Support') AND (d.code='IND_WAT_D03' OR d.name='Water Treatment and Utility Operations') AND (i.code='IND_WAT_001' OR i.name='Water Resources, Environment and Public Utilities');
 IF cardinality(ids) IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Missing/ambiguous production role context: Water Treatment Operations Assistant'; END IF;
 SELECT to_jsonb(x) INTO current_profile FROM public.role_family_roles x WHERE id=ids[1];
 IF NOT current_profile @> '{"description": "Water Treatment Operations Assistant supports support treatment-system operations in the RAREMINDS River Mission workplace case. May review operating evidence and support authorised teams; cannot start/alter plant operation, approve engineering designs or certify treatment safety.", "observable_behaviours": "Compare instrument values and operating/maintenance log entries; Review treatment performance indicators and constraints; Identify missing design, safety or technical-feasibility evidence; Prepare operator-facing deviation and authorised follow-up requests; Check each saved record against source ID, units, errors and role authority.", "role_work_context": "L2 measurement evidence \u2192 L4 treatment/option feasibility \u2192 L5 operations-route portfolio. Inputs: process and equipment readings, treatment-system records, maintenance evidence and intervention options. Course-wide foundations: CAP01, CAP02, CAP06, CAP07, CAP08, CAP11. Role focus: CAP04, CAP05, CAP09, CAP10. May review operating evidence and support authorised teams; cannot start/alter plant operation, approve engineering designs or certify treatment safety.", "typical_work_activities": "Water Treatment Operations Assistant: Compare instrument values and operating/maintenance log entries; Review treatment performance indicators and constraints; Identify missing design, safety or technical-feasibility evidence; Prepare operator-facing deviation and authorised follow-up requests. When source evidence is missing, record a HOLD/exception and identify the reviewing owner.", "role_output_evidence": "Source-backed outputs: Equipment and operating-parameter checklist; Treatment performance comparison; Engineering feasibility and evidence-gap assessment; Maintenance/deviation referral to qualified operator. Associated capability evidence: CAP01 Investigation brief; CAP02 Stakeholder and site register; CAP04 Sampling and test record; CAP05 Laboratory comparison sheet; CAP06 Validated analytical workbook; CAP07 Evidence and hypothesis matrix; CAP08 Criteria comparison and gap report; CAP09 Option evaluation model; CAP10 Project action pack; CAP11 Final professional investigation portfolio.", "primary_riasec": "R", "secondary_riasec": "I", "tertiary_riasec": "C", "riasec_reason": "RIC (Realistic/Investigative/Conventional): R fits equipment and physical systems; I fits process-failure reasoning; C fits procedure logs and maintenance controls. Proposed role-environment orientation, not an individual assessment.", "degree_gate": "Preferred", "direct_degree_mapping": "B.Tech Civil Engineering; B.Tech Environmental Engineering; B.Tech Chemical Engineering; B.Tech Mechanical Engineering; B.Tech Electrical and Electronics Engineering; B.Tech Electronics and Communication Engineering; B.Tech Instrumentation Engineering", "riasec_code_string": "RIC", "aptitude_profile": {"verbal_reasoning": 66, "logical_reasoning": 88, "numerical_reasoning": 87, "data_interpretation": 87, "pattern_recognition": 84, "spatial_reasoning": 89}, "big_five_profile": {"openness": 4, "conscientiousness": 5, "extraversion": 3, "agreeableness": 3, "emotional_stability": 5}, "work_values_profile": {"impact": 5, "status": 3, "autonomy": 3, "security": 5, "financial": 4, "lifestyle": 3, "creativity": 4, "leadership": 3}, "aptitude_assessment": {"areas": ["Logical Reasoning", "Spatial Reasoning", "Numerical Reasoning"], "rationale": "Evaluate flow/equipment conditions, recognise deviations, and interpret measured treatment performance. These are draft importance estimates for role requirements, not learner aptitude scores; SME review required."}, "big5_assessment": {"traits": ["Conscientiousness", "Emotional Stability", "Openness"], "rationale": "Careful operating judgement and calm escalation matter in safety-sensitive equipment environments. Trait-demand ratings are provisional role descriptors, not personality diagnosis or exclusion criteria."}, "work_values_assessment": {"values": ["Security", "Impact", "Creativity"], "rationale": "Reliable infrastructure and process improvement are central; hands-on interventions require operator clearance. Work-value ratings are provisional career-exploration descriptors, not employment or pay guarantees."}}'::jsonb THEN RAISE EXCEPTION 'Role profile differs from embedding input: Water Treatment Operations Assistant'; END IF;
