END $emb$;
DO $emb$ DECLARE ids uuid[]; current_profile jsonb; BEGIN
 SELECT array_agg(ctx.id) INTO ids FROM public.role_family_roles ctx
 JOIN public.role ro ON ro.id=ctx.role_id
 JOIN public.role_family_domains fd ON fd.id=ctx.role_family_domain_id
 JOIN public.role_families f ON f.id=fd.role_family_id
 JOIN public.industry_domains ds ON ds.id=fd.industry_domain_id
 JOIN public.domains d ON d.id=ds.domain_id
 JOIN public.industries i ON i.id=ds.industry_id
 WHERE (ro.code='WAT_RF05_DR01' OR ro.name='Environmental Compliance Support Associate') AND (f.code='WAT_RF05' OR f.name='Environmental Compliance Evidence') AND (d.code='IND_WAT_D04' OR d.name='Environmental Compliance and Public Programmes') AND (i.code='IND_WAT_001' OR i.name='Water Resources, Environment and Public Utilities');
 IF cardinality(ids) IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Missing/ambiguous production role context: Environmental Compliance Support Associate'; END IF;
 SELECT to_jsonb(x) INTO current_profile FROM public.role_family_roles x WHERE id=ids[1];
 IF NOT current_profile @> '{"description": "Environmental Compliance Support Associate supports track evidence against applicable requirements in the RAREMINDS River Mission workplace case. May prepare compliance evidence and flag deficiencies; cannot issue regulatory clearance, certify drinking-water safety or sign statutory compliance conclusions.", "observable_behaviours": "Compile monitoring, laboratory and method records with source IDs; Compare the correct parameter, test method, unit and criteria; Track evidence gaps, conditional approvals and reviewer status; Escalate unsupported compliance or safety claims; Check each saved record against source ID, units, errors and role authority.", "role_work_context": "L2 method/QC evidence \u2192 L3 criteria checks \u2192 L4 approval boundaries \u2192 L5 compliance-route portfolio. Inputs: monitoring register, method-verification fields, laboratory evidence, relevant reference criteria, approval and exception logs. Course-wide foundations: CAP01, CAP02, CAP06, CAP07, CAP08, CAP11. Role focus: CAP05, CAP08, CAP10. May prepare compliance evidence and flag deficiencies; cannot issue regulatory clearance, certify drinking-water safety or sign statutory compliance conclusions. Support-only degree pathways listed in source: B.Com, BA LLB, LLB.", "typical_work_activities": "Environmental Compliance Support Associate: Compile monitoring, laboratory and method records with source IDs; Compare the correct parameter, test method, unit and criteria; Track evidence gaps, conditional approvals and reviewer status; Escalate unsupported compliance or safety claims. When source evidence is missing, record a HOLD/exception and identify the reviewing owner.", "role_output_evidence": "Source-backed outputs: Monitoring and compliance evidence register; Methods-and-criteria comparison sheet; Gap and escalation register; Qualified compliance-support handover. Associated capability evidence: CAP01 Investigation brief; CAP02 Stakeholder and site register; CAP05 Laboratory comparison sheet; CAP06 Validated analytical workbook; CAP07 Evidence and hypothesis matrix; CAP08 Criteria comparison and gap report; CAP10 Project action pack; CAP11 Final professional investigation portfolio.", "primary_riasec": "C", "secondary_riasec": "I", "tertiary_riasec": "R", "riasec_reason": "CIR (Conventional/Investigative/Realistic): C fits structured records and requirements; I fits method and criteria interpretation; R reflects measurement-based site evidence. Proposed role-environment orientation, not an individual assessment.", "degree_gate": "Preferred", "direct_degree_mapping": "B.Sc. Chemistry; B.Sc. Environmental Science; B.Sc. Microbiology; B.Tech Civil Engineering; B.Tech Environmental Engineering; B.Tech Chemical Engineering; B.Com; BA Public Administration; BA Political Science; LLB; BA LLB", "riasec_code_string": "CIR", "aptitude_profile": {"verbal_reasoning": 84, "logical_reasoning": 86, "numerical_reasoning": 75, "data_interpretation": 91, "pattern_recognition": 80, "spatial_reasoning": 54}, "big_five_profile": {"openness": 4, "conscientiousness": 5, "extraversion": 3, "agreeableness": 4, "emotional_stability": 4}, "work_values_profile": {"impact": 5, "status": 3, "autonomy": 3, "security": 5, "financial": 3, "lifestyle": 3, "creativity": 3, "leadership": 3}, "aptitude_assessment": {"areas": ["Data Interpretation", "Logical Reasoning", "Verbal Reasoning"], "rationale": "Cross-check monitoring evidence, compare methods and requirements and write precise escalation notes. These are draft importance estimates for role requirements, not learner aptitude scores; SME review required."}, "big5_assessment": {"traits": ["Conscientiousness", "Emotional Stability", "Agreeableness"], "rationale": "Documentation accuracy and calm evidence-based escalation are essential where conclusions may affect people. Trait-demand ratings are provisional role descriptors, not personality diagnosis or exclusion criteria."}, "work_values_assessment": {"values": ["Impact", "Security", "Autonomy"], "rationale": "The work rewards traceability, responsibility and public impact; decisions belong to authorised compliance reviewers. Work-value ratings are provisional career-exploration descriptors, not employment or pay guarantees."}}'::jsonb THEN RAISE EXCEPTION 'Role profile differs from embedding input: Environmental Compliance Support Associate'; END IF;
