END $emb$;
DO $emb$ DECLARE ids uuid[]; current_profile jsonb; BEGIN
 SELECT array_agg(ctx.id) INTO ids FROM public.role_family_roles ctx
 JOIN public.role ro ON ro.id=ctx.role_id
 JOIN public.role_family_domains fd ON fd.id=ctx.role_family_domain_id
 JOIN public.role_families f ON f.id=fd.role_family_id
 JOIN public.industry_domains ds ON ds.id=fd.industry_domain_id
 JOIN public.domains d ON d.id=ds.domain_id
 JOIN public.industries i ON i.id=ds.industry_id
 WHERE (ro.code='WAT_RF06_DR01' OR ro.name='Water Resources / WASH Project Associate') AND (f.code='WAT_RF06' OR f.name='Water Resources and WASH Project Support') AND (d.code='IND_WAT_D04' OR d.name='Environmental Compliance and Public Programmes') AND (i.code='IND_WAT_001' OR i.name='Water Resources, Environment and Public Utilities');
 IF cardinality(ids) IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Missing/ambiguous production role context: Water Resources / WASH Project Associate'; END IF;
 SELECT to_jsonb(x) INTO current_profile FROM public.role_family_roles x WHERE id=ids[1];
 IF NOT current_profile @> '{"description": "Water Resources / WASH Project Associate supports coordinate community-facing water programmes in the RAREMINDS River Mission workplace case. May support programme coordination and consultations; cannot certify health claims, release sampling teams, approve budgets or speak as a public authority.", "observable_behaviours": "Document affected households and water uses without double counting; Coordinate field and stakeholder information with the assigned team; Maintain activity, issue, owner and progress registers; Draft evidence-based programme updates with unresolved needs; Check each saved record against source ID, units, errors and role authority.", "role_work_context": "L1 community and site evidence \u2192 L4 stakeholder/project actions \u2192 L5 WASH-route portfolio. Inputs: complaint records, site/stakeholder map, household water-use accounts, monitoring schedule and community activity logs. Course-wide foundations: CAP01, CAP02, CAP06, CAP07, CAP08, CAP11. Role focus: CAP02, CAP03, CAP10. May support programme coordination and consultations; cannot certify health claims, release sampling teams, approve budgets or speak as a public authority.", "typical_work_activities": "Water Resources / WASH Project Associate: Document affected households and water uses without double counting; Coordinate field and stakeholder information with the assigned team; Maintain activity, issue, owner and progress registers; Draft evidence-based programme updates with unresolved needs. When source evidence is missing, record a HOLD/exception and identify the reviewing owner.", "role_output_evidence": "Source-backed outputs: Stakeholder and water-use register; Community consultation and issue log; Water project progress and responsibility tracker; Supervised programme handover and feedback note. Associated capability evidence: CAP01 Investigation brief; CAP02 Stakeholder and site register; CAP03 Monitoring plan; CAP06 Validated analytical workbook; CAP07 Evidence and hypothesis matrix; CAP08 Criteria comparison and gap report; CAP10 Project action pack; CAP11 Final professional investigation portfolio.", "primary_riasec": "S", "secondary_riasec": "E", "tertiary_riasec": "C", "riasec_reason": "SEC (Social/Enterprising/Conventional): S fits community engagement and support; E fits coordination and follow-through; C fits reliable programme records. Proposed role-environment orientation, not an individual assessment.", "degree_gate": "Preferred", "direct_degree_mapping": "B.Sc. Zoology; B.Sc. Botany; B.Sc. Geography; B.Sc. Geology; B.Sc. Agriculture; B.F.Sc. Fisheries Science; BBA; MBA Operations; MBA Finance; MBA Sustainability; BA Economics; BA Sociology; BA Social Work; BSW; MSW; BA Public Administration; BA Political Science; BA Psychology; B.Sc. Psychology; Public Health programmes", "riasec_code_string": "SEC", "aptitude_profile": {"verbal_reasoning": 91, "logical_reasoning": 80, "numerical_reasoning": 76, "data_interpretation": 82, "pattern_recognition": 67, "spatial_reasoning": 72}, "big_five_profile": {"openness": 4, "conscientiousness": 5, "extraversion": 5, "agreeableness": 5, "emotional_stability": 4}, "work_values_profile": {"impact": 5, "status": 3, "autonomy": 3, "security": 4, "financial": 3, "lifestyle": 3, "creativity": 4, "leadership": 4}, "aptitude_assessment": {"areas": ["Verbal Reasoning", "Data Interpretation", "Logical Reasoning"], "rationale": "Convert community accounts into accurate registers, reconcile stakeholder needs and track project actions. These are draft importance estimates for role requirements, not learner aptitude scores; SME review required."}, "big5_assessment": {"traits": ["Agreeableness", "Conscientiousness", "Extraversion"], "rationale": "Clear communication and dependable follow-up support coordination without making unverified assurances. Trait-demand ratings are provisional role descriptors, not personality diagnosis or exclusion criteria."}, "work_values_assessment": {"values": ["Impact", "Leadership", "Autonomy"], "rationale": "Community impact and cooperative project work are central; accountability stays with the authorised project lead. Work-value ratings are provisional career-exploration descriptors, not employment or pay guarantees."}}'::jsonb THEN RAISE EXCEPTION 'Role profile differs from embedding input: Water Resources / WASH Project Associate'; END IF;
