END $emb$;
DO $emb$ DECLARE ids uuid[]; current_profile jsonb; BEGIN
 SELECT array_agg(ctx.id) INTO ids FROM public.role_family_roles ctx
 JOIN public.role ro ON ro.id=ctx.role_id
 JOIN public.role_family_domains fd ON fd.id=ctx.role_family_domain_id
 JOIN public.role_families f ON f.id=fd.role_family_id
 JOIN public.industry_domains ds ON ds.id=fd.industry_domain_id
 JOIN public.domains d ON d.id=ds.domain_id
 JOIN public.industries i ON i.id=ds.industry_id
 WHERE (ro.code='WAT_RF07_DR01' OR ro.name='Water Project Finance & Procurement Associate') AND (f.code='WAT_RF07' OR f.name='Water Project Financial Controls') AND (d.code='IND_WAT_D05' OR d.name='Water Project Finance and Procurement') AND (i.code='IND_WAT_001' OR i.name='Water Resources, Environment and Public Utilities');
 IF cardinality(ids) IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Missing/ambiguous production role context: Water Project Finance & Procurement Associate'; END IF;
 SELECT to_jsonb(x) INTO current_profile FROM public.role_family_roles x WHERE id=ids[1];
 IF NOT current_profile @> '{"description": "Water Project Finance & Procurement Associate supports control resources and expenditure in the RAREMINDS River Mission workplace case. May prepare financial analyses and recommendations; cannot approve a supplier, place a purchase order, authorise payment or treat conditional scope as spending approval.", "observable_behaviours": "Compare three vendor quotes including quantity, transport and technical evidence; Build the five-line quantity \u00d7 rate project budget; Separate proposed, conditional, committed, invoiced and paid amounts; Record procurement exceptions and approval dependencies; Check each saved record against source ID, units, errors and role authority.", "role_work_context": "L4 option costing, quote evaluation, procurement control \u2192 L5 finance-route portfolio. Inputs: vendor rates and technical eligibility documents, budget quantity/rate lines, APP-03 decision and ledger statuses. Course-wide foundations: CAP01, CAP02, CAP06, CAP07, CAP08, CAP11. Role focus: CAP09, CAP10. May prepare financial analyses and recommendations; cannot approve a supplier, place a purchase order, authorise payment or treat conditional scope as spending approval. Support-only degree pathways listed in source: B.Com.", "typical_work_activities": "Water Project Finance & Procurement Associate: Compare three vendor quotes including quantity, transport and technical evidence; Build the five-line quantity \u00d7 rate project budget; Separate proposed, conditional, committed, invoiced and paid amounts; Record procurement exceptions and approval dependencies. When source evidence is missing, record a HOLD/exception and identify the reviewing owner.", "role_output_evidence": "Source-backed outputs: Vendor quotation and technical eligibility matrix; Calculated budget and ceiling comparison; Approval/commitment/expenditure ledger; Finance and procurement exception handover. Associated capability evidence: CAP01 Investigation brief; CAP02 Stakeholder and site register; CAP06 Validated analytical workbook; CAP07 Evidence and hypothesis matrix; CAP08 Criteria comparison and gap report; CAP09 Option evaluation model; CAP10 Project action pack; CAP11 Final professional investigation portfolio.", "primary_riasec": "C", "secondary_riasec": "E", "tertiary_riasec": "I", "riasec_reason": "CEI (Conventional/Enterprising/Investigative): C supports controlled transaction evidence; E supports commercial comparison and vendor coordination; I supports eligibility checks and variance analysis. Proposed role-environment orientation, not an individual assessment.", "degree_gate": "Preferred", "direct_degree_mapping": "B.Com; BBA; MBA Operations; MBA Finance; MBA Sustainability; BA Economics", "riasec_code_string": "CEI", "aptitude_profile": {"verbal_reasoning": 84, "logical_reasoning": 87, "numerical_reasoning": 96, "data_interpretation": 94, "pattern_recognition": 76, "spatial_reasoning": 43}, "big_five_profile": {"openness": 3, "conscientiousness": 5, "extraversion": 3, "agreeableness": 4, "emotional_stability": 5}, "work_values_profile": {"impact": 4, "status": 3, "autonomy": 3, "security": 5, "financial": 4, "lifestyle": 3, "creativity": 3, "leadership": 4}, "aptitude_assessment": {"areas": ["Numerical Reasoning", "Data Interpretation", "Logical Reasoning"], "rationale": "Accurate rates, budgets, approval states and invoice checks require strong numerical and reconciliation skills. These are draft importance estimates for role requirements, not learner aptitude scores; SME review required."}, "big5_assessment": {"traits": ["Conscientiousness", "Emotional Stability", "Agreeableness"], "rationale": "Disciplined checks and sound escalation support decisions without crossing procurement authority boundaries. Trait-demand ratings are provisional role descriptors, not personality diagnosis or exclusion criteria."}, "work_values_assessment": {"values": ["Security", "Impact", "Financial Growth"], "rationale": "Transparent use of resources and financial control are meaningful; no compensation outcome is implied. Work-value ratings are provisional career-exploration descriptors, not employment or pay guarantees."}}'::jsonb THEN RAISE EXCEPTION 'Role profile differs from embedding input: Water Project Finance & Procurement Associate'; END IF;
