END $emb$;
DO $emb$ DECLARE ids uuid[]; current_profile jsonb; BEGIN
 SELECT array_agg(ctx.id) INTO ids FROM public.role_family_roles ctx
 JOIN public.role ro ON ro.id=ctx.role_id
 JOIN public.role_family_domains fd ON fd.id=ctx.role_family_domain_id
 JOIN public.role_families f ON f.id=fd.role_family_id
 JOIN public.industry_domains ds ON ds.id=fd.industry_domain_id
 JOIN public.domains d ON d.id=ds.domain_id
 JOIN public.industries i ON i.id=ds.industry_id
 WHERE (ro.code='WAT_RF08_DR01' OR ro.name='Water Monitoring Technology Associate') AND (f.code='WAT_RF08' OR f.name='Monitoring Devices and Sensor Evidence') AND (d.code='IND_WAT_D02' OR d.name='Environmental Data and Analysis') AND (i.code='IND_WAT_001' OR i.name='Water Resources, Environment and Public Utilities');
 IF cardinality(ids) IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Missing/ambiguous production role context: Water Monitoring Technology Associate'; END IF;
 SELECT to_jsonb(x) INTO current_profile FROM public.role_family_roles x WHERE id=ids[1];
 IF NOT current_profile @> '{"description": "Water Monitoring Technology Associate supports support digital monitoring systems in the RAREMINDS River Mission workplace case. May assess monitoring data and document device faults; cannot calibrate uncertified instruments, alter safety-critical devices or certify missing readings as valid.", "observable_behaviours": "Check device IDs and expected reporting intervals; Compare actual timestamps and station identifiers; Flag missing, duplicated or conflicting sensor readings; Record device exceptions and route them to the technical owner; Check each saved record against source ID, units, errors and role authority.", "role_work_context": "L2 instrument and sampling metadata \u2192 L3 dashboard exceptions \u2192 L5 monitoring-technology route. Inputs: device registry, monitoring station metadata, time fields, sensor-series logs and device-fault/maintenance evidence. Course-wide foundations: CAP01, CAP02, CAP06, CAP07, CAP08, CAP11. Role focus: CAP03, CAP04, CAP06. May assess monitoring data and document device faults; cannot calibrate uncertified instruments, alter safety-critical devices or certify missing readings as valid.", "typical_work_activities": "Water Monitoring Technology Associate: Check device IDs and expected reporting intervals; Compare actual timestamps and station identifiers; Flag missing, duplicated or conflicting sensor readings; Record device exceptions and route them to the technical owner. When source evidence is missing, record a HOLD/exception and identify the reviewing owner.", "role_output_evidence": "Source-backed outputs: Device/station mapping register; Timestamp-reconciliation and missing-data log; Monitoring dashboard exception report; Sensor fault and technical-support handover. Associated capability evidence: CAP01 Investigation brief; CAP02 Stakeholder and site register; CAP03 Monitoring plan; CAP04 Sampling and test record; CAP06 Validated analytical workbook; CAP07 Evidence and hypothesis matrix; CAP08 Criteria comparison and gap report; CAP11 Final professional investigation portfolio.", "primary_riasec": "R", "secondary_riasec": "I", "tertiary_riasec": "C", "riasec_reason": "RIC (Realistic/Investigative/Conventional): R fits field instruments and device constraints; I fits diagnostics and anomaly detection; C fits time-series consistency and traceability. Proposed role-environment orientation, not an individual assessment.", "degree_gate": "Preferred", "direct_degree_mapping": "B.Tech Electrical and Electronics Engineering; B.Tech Electronics and Communication Engineering; B.Tech Instrumentation Engineering; B.Tech Computer Science Engineering; B.Tech Information Technology; BCA; MCA; B.Sc. Data Science; B.Sc. Artificial Intelligence", "riasec_code_string": "RIC", "aptitude_profile": {"verbal_reasoning": 63, "logical_reasoning": 94, "numerical_reasoning": 90, "data_interpretation": 96, "pattern_recognition": 96, "spatial_reasoning": 85}, "big_five_profile": {"openness": 5, "conscientiousness": 5, "extraversion": 2, "agreeableness": 3, "emotional_stability": 4}, "work_values_profile": {"impact": 5, "status": 3, "autonomy": 4, "security": 4, "financial": 4, "lifestyle": 3, "creativity": 5, "leadership": 3}, "aptitude_assessment": {"areas": ["Pattern Recognition", "Data Interpretation", "Logical Reasoning"], "rationale": "Detect missing intervals, mismatched timestamps, device faults and inconsistent monitoring data. These are draft importance estimates for role requirements, not learner aptitude scores; SME review required."}, "big5_assessment": {"traits": ["Conscientiousness", "Openness", "Emotional Stability"], "rationale": "Systematic diagnostics and careful exception documentation prevent false monitoring conclusions. Trait-demand ratings are provisional role descriptors, not personality diagnosis or exclusion criteria."}, "work_values_assessment": {"values": ["Impact", "Creativity", "Autonomy"], "rationale": "The work supports useful technical innovation, but a device fault record is not an instrument-calibration certificate. Work-value ratings are provisional career-exploration descriptors, not employment or pay guarantees."}}'::jsonb THEN RAISE EXCEPTION 'Role profile differs from embedding input: Water Monitoring Technology Associate'; END IF;
