END $emb$;
DO $emb$ DECLARE ids uuid[]; current_profile jsonb; BEGIN
 SELECT array_agg(ctx.id) INTO ids FROM public.role_family_roles ctx
 JOIN public.role ro ON ro.id=ctx.role_id
 JOIN public.role_family_domains fd ON fd.id=ctx.role_family_domain_id
 JOIN public.role_families f ON f.id=fd.role_family_id
 JOIN public.industry_domains ds ON ds.id=fd.industry_domain_id
 JOIN public.domains d ON d.id=ds.domain_id
 JOIN public.industries i ON i.id=ds.industry_id
 WHERE (ro.code='WAT_RF09_DR01' OR ro.name='Environmental Communication Associate') AND (f.code='WAT_RF09' OR f.name='Environmental Communication and Outreach') AND (d.code='IND_WAT_D04' OR d.name='Environmental Compliance and Public Programmes') AND (i.code='IND_WAT_001' OR i.name='Water Resources, Environment and Public Utilities');
 IF cardinality(ids) IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Missing/ambiguous production role context: Environmental Communication Associate'; END IF;
 SELECT to_jsonb(x) INTO current_profile FROM public.role_family_roles x WHERE id=ids[1];
 IF NOT current_profile @> '{"description": "Environmental Communication Associate supports communicate findings responsibly in the RAREMINDS River Mission workplace case. May draft and explain evidence for review; cannot declare water safe, attribute blame, issue government notices or publish an unapproved statement.", "observable_behaviours": "Identify the exact verified finding and the remaining uncertainty; Translate technical measurements into plain-language stakeholder updates; Draft community notices without unsupported blame or safety assurance; Track reviewer approval, publication status and questions raised; Check each saved record against source ID, units, errors and role authority.", "role_work_context": "L1 community concerns \u2192 L3 qualified findings \u2192 L4 notices \u2192 L5 communication-route portfolio. Inputs: complaint statements, stakeholder concerns, verified measurements, qualified findings and reviewer/issue status. Course-wide foundations: CAP01, CAP02, CAP06, CAP07, CAP08, CAP11. Role focus: CAP02, CAP08, CAP10. May draft and explain evidence for review; cannot declare water safe, attribute blame, issue government notices or publish an unapproved statement.", "typical_work_activities": "Environmental Communication Associate: Identify the exact verified finding and the remaining uncertainty; Translate technical measurements into plain-language stakeholder updates; Draft community notices without unsupported blame or safety assurance; Track reviewer approval, publication status and questions raised. When source evidence is missing, record a HOLD/exception and identify the reviewing owner.", "role_output_evidence": "Source-backed outputs: Factual stakeholder update and briefing note; Concern and response register; Draft public notice with evidence sources; Communication review and issue-status handover. Associated capability evidence: CAP01 Investigation brief; CAP02 Stakeholder and site register; CAP06 Validated analytical workbook; CAP07 Evidence and hypothesis matrix; CAP08 Criteria comparison and gap report; CAP10 Project action pack; CAP11 Final professional investigation portfolio.", "primary_riasec": "S", "secondary_riasec": "A", "tertiary_riasec": "E", "riasec_reason": "SAE (Social/Artistic/Enterprising): S fits audience concerns and understanding; A fits accessible clear presentation; E fits message delivery and stakeholder coordination. Proposed role-environment orientation, not an individual assessment.", "degree_gate": "Preferred", "direct_degree_mapping": "BA Sociology; BA Social Work; BSW; MSW; BA Psychology; B.Sc. Psychology; BA Journalism; BA Mass Communication", "riasec_code_string": "SAE", "aptitude_profile": {"verbal_reasoning": 96, "logical_reasoning": 78, "numerical_reasoning": 60, "data_interpretation": 82, "pattern_recognition": 68, "spatial_reasoning": 49}, "big_five_profile": {"openness": 5, "conscientiousness": 4, "extraversion": 5, "agreeableness": 5, "emotional_stability": 4}, "work_values_profile": {"impact": 5, "status": 3, "autonomy": 4, "security": 3, "financial": 3, "lifestyle": 4, "creativity": 5, "leadership": 4}, "aptitude_assessment": {"areas": ["Verbal Reasoning", "Data Interpretation", "Logical Reasoning"], "rationale": "Accurate public explanations require interpreting technical facts, simplifying language and checking what the evidence cannot prove. These are draft importance estimates for role requirements, not learner aptitude scores; SME review required."}, "big5_assessment": {"traits": ["Agreeableness", "Openness", "Conscientiousness"], "rationale": "Empathy and careful wording help communicate uncertainty without unnecessary alarm or false assurance. Trait-demand ratings are provisional role descriptors, not personality diagnosis or exclusion criteria."}, "work_values_assessment": {"values": ["Impact", "Creativity", "Leadership"], "rationale": "Clear public understanding and accessible communication matter; publication is subject to authorised review. Work-value ratings are provisional career-exploration descriptors, not employment or pay guarantees."}}'::jsonb THEN RAISE EXCEPTION 'Role profile differs from embedding input: Environmental Communication Associate'; END IF;
